@section('content')
<x-hris.table id="notifications-table" endpoint="/api/notifications" :columns="[['key'=>'title','label'=>'Title'],['key'=>'meta','label'=>'Message'],['key'=>'source','label'=>'Source'],['key'=>'priority','label'=>'Priority'],['key'=>'is_read','label'=>'Read']]" :actions="[['name'=>'open','label'=>'Open'],['name'=>'read','label'=>'Mark read'],['name'=>'dismiss','label'=>'Dismiss']]"/>
@can('notifications.publish')<x-hris.modal id="notification-publish" title="Publish notification"><form id="notification-form" data-endpoint="/api/notifications/create"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="title" required/><x-hris.field name="message" type="textarea" required/><x-hris.field name="notification_type" label="Audience" type="select" :options="['personal'=>'Personal','broadcast'=>'Current employees','role_based'=>'Selected roles']" required/><x-hris.employee-picker name="user_id" label="Personal recipient"/><div class="col-md-6"><label for="notice-roles" class="form-label">Recipient roles</label><select name="target_roles" id="notice-roles" class="form-select" multiple>@foreach(array_keys(config('hris.roles')) as $role)<option value="{{ $role }}">{{ ucwords(str_replace('_',' ',$role)) }}</option>@endforeach</select></div><x-hris.field name="url" label="Destination (local path or approved HTTPS URL)"/><x-hris.field name="priority" type="number" min="0" max="10" value="5"/><x-hris.field name="expires_at" type="datetime-local"/></div></div><div class="modal-footer"><button class="btn btn-primary">Publish</button></div></form></x-hris.modal>@endcan
@endsection
@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#notifications-table'),form=document.querySelector('#notification-form');const refresh=()=>{table.table.load();window.dispatchEvent(new Event('notifications:changed'))};if(form)HRIS.bindForm(form,{prepare:body=>{body.target_roles=[...form.elements.target_roles.selectedOptions].map(o=>o.value)},success:refresh});document.querySelectorAll('[data-notice-action]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{HRIS.feedback((await HRIS.request(`/api/notifications/${button.dataset.noticeAction}`,{method:'POST'})).message);refresh()}catch(error){HRIS.feedback(error.message,true)}finally{button.disabled=false}});table.addEventListener('table:action',async({detail:{action,row}})=>{try{await HRIS.request(`/api/notifications/${action==='open'?'read':action}`,{method:'POST',body:{id:row.notification_id}});if(action==='open'){if(row.url)window.location.assign(row.url);else HRIS.showDetails(row.title,{message:row.meta,source:row.source})}refresh()}catch(error){HRIS.feedback(error.message,true)}})});</script>@endpush
